
DROP TABLE IF EXISTS postgis_garden_log35;
CREATE TABLE postgis_garden_log35(logid serial PRIMARY KEY, log_label text, spatial_class text, func text, g1 text, g2 text, log_start timestamp, log_end timestamp, log_sql text);
DROP TABLE IF EXISTS postgis_garden_log35_output;
CREATE TABLE postgis_garden_log35_output(logid integer PRIMARY KEY, log_output xml);

                
