INSERT INTO postgis_garden_log35(log_label, func, g1, log_start, log_sql)
VALUES('table Test POINT AddGeometryColumn','AddGeometryColumn', 'POINT', clock_timestamp(),
    'CREATE TABLE pgis_garden (gid serial);
	SELECT AddGeometryColumn(''pgis_garden'',''the_geom'',ST_SRID(the_geom),GeometryType(the_geom),ST_CoordDim(the_geom))
			FROM ((SELECT ST_SetSRID(ST_Point(i,j),4326) As the_geom
		FROM (SELECT a*1.11111111 FROM generate_series(-10,50,2) As a) As i(i)
			CROSS JOIN generate_series(40,70, 5) j
			ORDER BY i,j
			)) As foo limit 1;
	SELECT AddGeometryColumn(''pgis_garden'',''the_geom_multi'',ST_SRID(the_geom),GeometryType(ST_Multi(the_geom)),ST_CoordDim(the_geom)) FROM ((SELECT ST_SetSRID(ST_Point(i,j),4326) As the_geom FROM (SELECT a*1.11111111 FROM generate_series(-10,50,2) As a) As i(i) CROSS JOIN generate_series(40,70, 5) j ORDER BY i,j )) As foo limit 1;');
BEGIN;
	CREATE TABLE pgis_garden (gid serial);
